import {createHistoryReviewClient} from './history-review-client.js';
import {normalizeHistoryReview,reviewMatches,planHistoryReview} from './relationship-review.js';
import {normalizeWorkspace} from './workspace.js';
import {libraryDate} from './library-ui.js';
export function createRelationshipReviewUI(api){
 const {getState,current,modal,escape:esc,persist,toast}=api;let task={status:'none'},error='',openingChat=null,submitting=false;
 const pair=()=>{const s=getState();return {endpoint:s.endpoint||location.origin,token:s.token};};
 function apply(raw,chatId){const state=getState(),chat=state.chats.find(chat=>chat.id===chatId);if(!chat)return;const review=normalizeHistoryReview(raw,new Map([...(chat.archive||[]),...chat.messages].map(m=>[m.id,m])));if(!reviewMatches(review,chat))throw new Error('这次梳理的历史或背景已经变更，结果未覆盖当前资料。请按新历史重新梳理。');if(chat.relationshipReview?.sourceHash===review.sourceHash)return;if(reviewMatches(chat.relationshipReview,chat)&&chat.relationshipReview.sourceCount>review.sourceCount)return;
  const next={...chat,relationshipReview:review,reviewUpdatedAt:Math.max(Date.now(),(chat.reviewUpdatedAt||0)+1)};normalizeWorkspace({...state,chats:state.chats.map(c=>c.id===chatId?next:c)});Object.assign(chat,next);persist();if(chat.id===state.active){const badge=document.querySelector('.contact-progress [data-action="global-review"]');if(badge)badge.textContent='关系档案 · 已覆盖 '+review.sourceCount+' 条';}toast('整段历史已梳理，关系档案已保存。后续回复会参考有依据的部分。');render();
 }
 const client=createHistoryReviewClient({getPair:pair,onUpdate:value=>{task=value;submitting=false;error='';render();},onComplete:apply,onError:issue=>{error=issue.message;submitting=false;if(task.status==='running')task={...task,status:'failed'};render();}});
 function citations(item){return item.evidence.map(position=>`<button class="citation" data-review-evidence="${position}">历史原话 ${position}</button>`).join('');}
 function render(){const root=document.querySelector('#relationship-review-body');if(!root||current().id!==openingChat)return;const chat=current(),review=chat.relationshipReview,plan=planHistoryReview(chat.messages),running=task.status==='running'||submitting,owner=getState().chats.find(c=>c.id===task.chatId)?.name||'该联系人',progress=task.progress,matched=reviewMatches(review,chat);
  root.innerHTML=`<details ${!review||running?'open':''}><summary>梳理范围与更新选项</summary><div class="notice">已导入 ${chat.messages.length} 条。将按顺序分 ${plan.chunks.length} 段梳理并汇总，最多约 ${plan.calls} 次模型处理，使用 Mac 上的 Codex 额度。已完成的相同分段可复用。开始后，已导入的全部聊天文字和背景会分批通过 Codex 发送给 OpenAI。Mac 需保持运行，关闭手机页面后仍可继续。</div><p class="intro">关系档案区分原话、可能解释与待确认问题；不能确定对方真实心理，也不会把几次表现当作稳定人格。</p><div class="history-paging"><button class="outline-btn" data-action="profile">补充关系背景</button><button class="primary-btn" data-review-control="start" ${running||!chat.messages.length?'disabled':''}>${review?'更新 / 继续全量梳理':'开始 / 继续全量梳理'}</button>${running?`<button class="outline-btn" data-review-control="cancel" ${!task.jobId?'disabled':''}>停止 ${esc(owner)} 的梳理</button>`:''}<button class="outline-btn" data-review-control="refresh">刷新进度</button></div></details>${running?`<div class="context-coverage" role="status">正在为 ${esc(owner)} 处理 · ${esc(progress?.phase||'准备任务')}<br>${progress?`已完成 ${progress.done} / ${progress.total} 步，复用 ${progress.cached} 步。`:''}停止后可复用已完成的分段。</div>`:''}${error?`<p class="error" role="alert">${esc(error)} 已有档案和原聊天仍保留。</p>`:''}${task.status==='cancelled'?'<p class="intro">已停止。可以点击继续，复用已完成的分段。</p>':''}${review?`<div class="context-coverage">档案覆盖 ${review.sourceCount} 条 · ${review.chunkCount} 段 · ${libraryDate(review.createdAt,true)}<br>${matched?(chat.messages.length>review.sourceCount?`另有 ${chat.messages.length-review.sourceCount} 条新消息待更新；现有档案仅代表此前历史。`:'与当前已导入的历史一致。'):'原历史或背景已改变，此档案不用于当前回复；请重新梳理。'}</div><h3>${esc(review.report.headline)}</h3><p class="review-summary">${esc(review.report.summary)}</p><h3>近期可能的状态</h3>${observation(review.report.recentState)}${section('你们的关系进展',review.report.stages)}<h3>聊天中呈现的沟通表现</h3>${review.report.observations.map(observation).join('')||'<p>现有材料不足以归纳。</p>'}${section('尚待处理或确认的事',review.report.openLoops)}${section('当前适合怎么沟通',review.report.nextSteps)}<h3>仍需确认</h3>${review.report.unknowns.map(text=>`<p>• ${esc(text)}</p>`).join('')}`:'<p class="intro">首次使用：先导入同一人的旧聊天，再开始梳理。完成后可逐条查看原话依据；以后追加新消息，再更新档案。</p>'}`;
 }
 function observation(item){return `<article class="memory-item"><small>${item.confidence==='explicit'?'原话中的明确表达，仅代表当时':'可能的解释，需确认'}</small><p>${esc(item.text)}</p><p class="intro">其他解释 / 局限：${esc(item.alternative)}</p>${citations(item)}</article>`;}
 function section(title,items){return `<h3>${title}</h3>${items.map(item=>`<article class="memory-item"><p>${esc(item.text)}</p>${citations(item)}</article>`).join('')||'<p>暂未找到足够依据。</p>'}`;}
 function open(){openingChat=current().id;modal('全量历史梳理与关系档案','把已导入的整段聊天逐段梳理，后续回复继续参考。','<div id="relationship-review-body"></div>','<button class="primary-btn" data-action="close-modal">返回聊天</button>');render();if(getState().token)void resume();}
 async function resume(){if(!getState().token)return;await client.resume(pair());}
 document.addEventListener('click',async event=>{const b=event.target.closest('button');if(!b)return;try{if(b.dataset.reviewControl){if(!getState().token)throw new Error('请先连接 Mac，再进行全量历史梳理。');if(b.dataset.reviewControl==='start'){if(['late','tired','weekend'].includes(current().id))throw new Error('请先导入自己的聊天，再梳理实际关系。');submitting=true;task={status:'running'};error='';render();const chat=current();await client.start(pair(),{chatId:chat.id,note:chat.note||'',messages:chat.messages.map(m=>({id:m.id,role:m.role,text:m.text,...(m.sentAt?{sentAt:m.sentAt}:{})}))});}else if(b.dataset.reviewControl==='cancel'){b.disabled=true;await client.cancel();}else if(b.dataset.reviewControl==='refresh')await resume();}
  else if(b.dataset.reviewEvidence){const chat=current(),review=chat.relationshipReview,position=Number(b.dataset.reviewEvidence),id=review?.sourceIds[position-1],message=[...(chat.archive||[]),...chat.messages].find(m=>m.id===id);if(!message)throw new Error('原话已变更，请刷新档案。');modal('关系梳理的原话依据',`完整历史第 ${position} 条 · ${message.role==='me'?'我':esc(chat.name)} · ${message.sentAt?'发言于 '+libraryDate(message.sentAt,true):'发言时间未知'}`,`<p class="review-summary">${esc(message.text)}</p>`,'<button class="primary-btn" data-action="global-review">返回关系档案</button>');}
 }catch(issue){error=issue.message;submitting=false;render();toast(issue.message);}});
 return {open,resume,disconnect:()=>{client.disconnect();task={status:'none'};submitting=false;}};
}
